tool_input.command:
$targetRef = 'origin/suzhou-taicang-wuguan-dev-v1.26'
$bootstrap = git -C 'D:\repository\太仓物管后端' show "${targetRef}:zhishu-company/src/main/resources/bootstrap.yml" 2>$null
if ($LASTEXITCODE -ne 0) { 'BOOTSTRAP_READ_FAILED'; exit 2 }
$text = $bootstrap -join "`n"
$userMatch = [regex]::Match($text, '(?im)^\s*username:\s*["'']?([^"''#\s]+)')
$passMatch = [regex]::Match($text, '(?im)^\s*password:\s*["'']?([^"''#\s]+)')
if (-not $userMatch.Success -or -not $passMatch.Success) { 'NACOS_CREDENTIAL_KEYS_NOT_FOUND'; exit 3 }
try {
  $login = Invoke-WebRequest -Uri 'http://192.168.1.12:8848/nacos/v1/auth/users/login' -Method Post -Body @{ username=$userMatch.Groups[1].Value; password=$passMatch.Groups[1].Value } -SkipHttpErrorCheck -TimeoutSec 15
  'NACOS_LOGIN_HTTP=' + [int]$login.StatusCode
  $body = $login.Content | ConvertFrom-Json -ErrorAction SilentlyContinue
  $token = if ($body.accessToken) { $body.accessToken } elseif ($body.token) { $body.token } else { '' }
  if ([int]$login.StatusCode -ge 200 -and [int]$login.StatusCode -lt 300 -and $token) {
    $url = 'http://192.168.1.12:8848/nacos/v1/cs/configs?dataId=shared-druid-dev.yml&group=DEFAULT_GROUP&tenant=zscloud&accessToken=' + [uri]::EscapeDataString($token)
    $cfg = Invoke-WebRequest -Uri $url -Method Get -SkipHttpErrorCheck -TimeoutSec 15
    'NACOS_CONFIG_HTTP=' + [int]$cfg.StatusCode
    if ([int]$cfg.StatusCode -eq 200) {
      $cfgText = [string]$cfg.Content
      $dbUrl = [regex]::Match($cfgText, '(?im)^\s*url:\s*["'']?([^"''\r\n]+)')
      $dbDriver = [regex]::Match($cfgText, '(?im)^\s*driver-class-name:\s*["'']?([^"''\r\n]+)')
      $dbUser = [regex]::Match($cfgText, '(?im)^\s*username:\s*["'']?([^"''\r\n]+)')
      if ($dbUrl.Success) { 'DB_URL=' + ($dbUrl.Groups[1].Value -replace '(?i)(password|pwd)=([^;&]+)','$1=[redacted]') } else { 'DB_URL_NOT_FOUND' }
      if ($dbDriver.Success) { 'DB_DRIVER=' + $dbDriver.Groups[1].Value }
      if ($dbUser.Success) { 'DB_USERNAME=' + $dbUser.Groups[1].Value }
      'DB_PASSWORD_PRESENT=' + [bool]([regex]::IsMatch($cfgText, '(?im)^\s*password:\s*\S+'))
    }
  }
} catch {
  'NACOS_HTTP_DIAGNOSTIC_FAILED=' + $_.Exception.GetType().Name
}
